import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const i=JSON.parse('{"title":"九叹·远游","description":"","frontmatter":{"title":"九叹·远游","date":"2026-11-24T00:00:00.000Z","seq":56,"categories":["美文","楚辞"],"collection":"《楚辞》","tags":["楚辞","先秦"],"poem":true,"poem_quote":false,"author":"刘向","source_book":"楚辞","prev":{"text":"思古","link":"/blogs/楚辞/思古.html"},"next":{"text":"逢尤","link":"/blogs/楚辞/逢尤.html"}},"headers":[],"relativePath":"blogs/楚辞/九叹·远游.md","filePath":"blogs/楚辞/九叹·远游.md"}'),o={name:"blogs/楚辞/九叹·远游.md"};function l(n,a,c,m,z,r){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="九叹·远游" tabindex="-1">九叹·远游 <a class="header-anchor" href="#九叹·远游" aria-label="Permalink to &quot;九叹·远游&quot;">​</a></h1><p class="poem-meta">先秦 · 刘向　·　九叹</p><div class="poem"><p class="poem-stanza">悲余性之不可改兮，屡惩艾而不迻。</p><p class="poem-stanza">服觉皓以殊俗兮，貌揭揭以巍巍。</p><p class="poem-stanza">譬若王侨之乘云兮，载赤霄而凌太清。</p><p class="poem-stanza">欲与天地参寿兮，与日月而比荣。</p><p class="poem-stanza">登昆仑而北首兮，悉灵圉而来谒。</p><p class="poem-stanza">选鬼神于太阴兮，登阊阖于玄阙。</p><p class="poem-stanza">回朕车俾西引兮，褰虹旗于玉门。</p><p class="poem-stanza">驰六龙于三危兮，朝西灵于九滨。</p><p class="poem-stanza">结余轸于西山兮，横飞谷以南征。</p><p class="poem-stanza">绝都广以直指兮，历祝融于硃冥。</p><p class="poem-stanza">枉玉衡于炎火兮，委两馆于咸唐。</p><p class="poem-stanza">贯澒濛以东朅兮，维六龙于扶桑。</p><p class="poem-stanza">周流览于四海兮，志升降以高驰。</p><p class="poem-stanza">徵九神于回极兮，建虹采以招指。</p><p class="poem-stanza">驾鸾凤以上游兮，从玄鹤与鹪明。</p><p class="poem-stanza">孔鸟飞而送迎兮，腾群鹤于瑶光。</p><p class="poem-stanza">排帝宫与罗囿兮，升县圃以眩灭。</p><p class="poem-stanza">结琼枝以杂佩兮，立长庚以继日。</p><p class="poem-stanza">凌惊雷以轶骇电兮，缀鬼谷于北辰。</p><p class="poem-stanza">鞭风伯使先驱兮，囚灵玄于虞渊。</p><p class="poem-stanza">遡高风以低佪兮，览周流于朔方。</p><p class="poem-stanza">就颛顼而敶辞兮，考玄冥于空桑。</p><p class="poem-stanza">旋车逝于崇山兮，奏虞舜于苍梧。</p><p class="poem-stanza">济杨舟于会稽兮，就申胥于五湖。</p><p class="poem-stanza">见南郢之流风兮，殒余躬于沅湘。</p><p class="poem-stanza">望旧邦之黯黮兮，时溷浊其犹未央。</p><p class="poem-stanza">怀兰茝之芬芳兮，妒被离而折之。</p><p class="poem-stanza">张绛帷以襜襜兮，风邑邑而蔽之。</p><p class="poem-stanza">日暾暾其西舍兮，阳焱焱而复顾。</p><p class="poem-stanza">聊假日以须臾兮，何骚骚而自故。</p><p class="poem-stanza">叹曰：</p><p class="poem-stanza">譬彼蛟龙乘云浮兮，汎淫澒溶纷若雾兮。</p><p class="poem-stanza">潺湲轇轕雷动电发馺高举兮。</p><p class="poem-stanza">升虚凌冥沛浊浮清入帝宫兮，摇翘奋羽驰风骋雨游无穷兮。</p></div>',3)])])}const d=s(o,[["render",l]]);export{i as __pageData,d as default};
